mapper.select:
SELECT review_request_id, reviewer_id, review_status FROM strategy_review_request WHERE strategy_option_id = #{strategyOptionId} AND is_deleted = 0 AND reviewer_id IN
#{reviewerId}
ORDER BY reviewer_id

mapper.update:
UPDATE strategy_case
SET case_status = 'READY_TO_EXECUTE',
    updated_at = SYSTIMESTAMP,
    updated_by = #{actorId}
WHERE strategy_case_id = #{strategyCaseId}
  AND case_status = 'GENERATED'
  AND is_deleted = 0
  AND EXISTS (
      SELECT 1
      FROM strategy_review_request request
      WHERE request.strategy_option_id = #{strategyOptionId}
        AND request.is_deleted = 0
  )
  AND NOT EXISTS (
      SELECT 1
      FROM strategy_review_request request
      WHERE request.strategy_option_id = #{strategyOptionId}
        AND request.review_status != 'SENT'
        AND request.is_deleted = 0
  )
